 "content": "def transform(grid):
    g = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return g
    h, w = len(grid), len(grid[0])
    def motif_count(p):
        r, c = p
        return sum(1 for rr in range(h) for cc in range(w)
                   if (rr, cc) != p and grid[rr][cc] != 0)
    source = max(markers, key=motif_count)
    target = next(p for p in markers if p != source)
    sr, sc = source
    tr, tc = target
    # The colored pattern around one marker is translated to the other marker.
    offsets = [(r - sr, c - sc, grid[r][c])
               for r in range(h) for c in range(w)
               if (r, c) != source and grid[r][c] != 0]
    # Clear the destination marker, then place the translated pattern.
    g[tr][tc] = 0
    for dr, dc, color in offsets:
        rr, cc = tr + dr, tc + dc
        if 0 <= rr < h and 0 <= cc < w:
            g[rr][cc] = color
    return g
